#!/usr/bin/env bash
# glitch-cli-tools bundle - self-extracting installer
# Rebuilds each tool from embedded base64 into /bin and sets permissions.
if [[ $EUID -ne 0 ]]; then
    echo "> must run as root:  sudo bash $0"
    exit 1
fi
cd /bin
echo "> installing glitch-cli-tools into $(pwd)"
